/* A single readable column for the conversation and its composer. */
#messages,#composer,.typing-line,.reply-draft,.composer-status{width:100%;max-width:none;margin-left:auto;margin-right:auto}
.session-check #gate>:not(.gate-art){visibility:hidden}
.message-footer{display:flex;align-items:center;gap:18px;margin-top:7px;min-height:34px}
.message-tools>[data-action=more]{margin-left:auto}
.heart-button{--heart:#b5193c;display:inline-flex;align-items:center;justify-content:flex-start;gap:7px;position:relative;min-width:45px;min-height:30px;padding:3px 0;border-radius:5px;color:#4e3025;font-size:14px;line-height:1;transition:color .2s;overflow:visible}
.heart-button:disabled{opacity:1}.heart-button.is-liked,.heart-button:hover:not(:disabled){color:var(--heart)}
.heart-symbol{display:grid;place-items:center;position:relative;width:26px;height:26px;flex-shrink:0}
.heart-symbol svg{width:21px;height:21px;fill:transparent;transition:fill .18s,stroke .18s;overflow:visible}
.heart-button.is-liked .heart-symbol svg{fill:currentColor;stroke:currentColor}
.heart-count{font-variant-numeric:tabular-nums;min-width:1ch;text-align:left}
.heart-symbol::before,.heart-symbol::after{content:"";position:absolute;pointer-events:none;opacity:0}
.heart-symbol::before{inset:4px;border:2px solid var(--heart);border-radius:50%}
.heart-symbol::after{width:3px;height:3px;border-radius:50%;background:transparent;color:var(--heart);box-shadow:0 -17px,15px -8px,15px 8px,0 17px,-15px 8px,-15px -8px}
.heart-pop .heart-symbol svg{animation:heart-beat .44s var(--ease)}.heart-pop .heart-symbol::before{animation:heart-ring .4s ease-out}.heart-pop .heart-symbol::after{animation:heart-spark .46s ease-out}.heart-pop .heart-count{animation:heart-count .28s var(--ease)}
@keyframes heart-beat{0%{transform:scale(.75)}40%{transform:scale(1.24)}72%{transform:scale(.94)}100%{transform:scale(1)}}
@keyframes heart-ring{0%{transform:scale(.3);opacity:.7}80%,100%{transform:scale(1.8);opacity:0}}
@keyframes heart-spark{0%{transform:scale(.3);opacity:0}30%{opacity:.8}100%{transform:scale(1.15);opacity:0}}
@keyframes heart-count{from{transform:translateY(3px);opacity:.5}to{transform:none;opacity:1}}
.picker-heart svg{width:21px;height:21px;fill:#e83c58;stroke:#e83c58}
.card-actions>.heart-button{padding:3px 0;font-size:14px}
.wallet-dialog{max-width:408px;padding:24px}.wallet-options{display:grid;gap:0}
.wallet-option{display:flex;align-items:center;gap:16px;min-height:68px;width:100%;padding:12px 6px;text-align:left;border:0;border-bottom:1px solid #211e1929;border-radius:0;font-size:18px;animation:wallet-arrive .32s var(--ease) both}
.wallet-option:nth-child(2){animation-delay:45ms}.wallet-option:nth-child(3){animation-delay:90ms}
.wallet-option img{display:block;width:36px;height:36px;object-fit:contain;flex-shrink:0}
.wallet-option:nth-of-type(3){border-bottom:0}.wallet-option:hover{background:#00000005;transform:translateX(3px)}
.wallet-note{font-size:12px;line-height:1.6;color:#75654f;text-align:center;margin:4px 0 0}.wallet-note:empty{display:none}
@keyframes wallet-arrive{from{opacity:0;transform:translateY(7px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:600px){.message-footer{gap:16px;margin-top:7px}.message-tools{gap:12px}.wallet-dialog{padding:22px}.wallet-option{min-height:64px}.composer-wrap{padding-left:12px;padding-right:10px}.gate{height:calc(100dvh - 94px)}}
@media(prefers-reduced-motion:reduce){.heart-pop .heart-symbol svg,.heart-pop .heart-symbol::before,.heart-pop .heart-symbol::after,.heart-pop .heart-count,.wallet-option{animation:none!important}}

.poll-option{font-size:17px;min-height:50px;border-color:#211e1960;border-radius:6px}.poll-option::before{background:#211e1917}.poll-option[aria-pressed=true]{background:#211e1912}.quoted{font-size:14px;white-space:pre-wrap;line-height:1.4;padding:8px 10px;border-color:#472e22;background:#00000007}.card-actions .heart-button.is-liked{color:var(--heart)}
@media(max-width:600px){.club-shell{padding:16px 16px max(14px,env(safe-area-inset-bottom))}.club-header #account{font-size:11px;min-width:0}.club-header{grid-template-columns:1fr auto;gap:5px}.club-header h1{font-size:25px}.idea-card h3,.poll-card h3{font-size:23px}.form-field input,.form-field textarea,.form-field select{font-size:16px}.message-tools>button{height:34px;width:34px}}

/* All three club rooms stay open. Each room owns its scrolling area. */
body.club-connected .club-shell{max-width:1440px}
.club-header:has(#club-title:not([hidden])){grid-template-columns:1fr auto 1fr}
.club-header h1{font-size:30px;text-align:center}
.club-panels{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}
.club-panel{display:flex;flex-direction:column;min-width:0;height:clamp(520px,calc(100dvh - 150px - var(--context)),860px);min-height:0;max-height:none;overflow:hidden;padding:0;border:1px solid #211e1955;border-radius:11px;background:#ffffff05}
.panel-heading{height:66px;min-height:66px;display:flex;align-items:center;justify-content:space-between;gap:10px;padding:0 18px;border-bottom:1px solid #211e1929}
.panel-heading h2{font-size:22px;font-weight:500;letter-spacing:-.45px;line-height:1.2}
.panel-actions{display:flex;align-items:center;gap:12px}
.panel-add{padding:8px 0;font-size:13px;white-space:nowrap;text-underline-offset:3px}
.panel-add:hover:not(:disabled){text-decoration:underline}
.vote-help{width:23px;height:23px;border:1px solid #211e1966;border-radius:50%;padding:0;font-size:13px;line-height:21px}
.feed,.panel-content{flex:1;min-height:0;overflow:auto;overscroll-scrollbar-width:thin;scrollbar-color:#29272150 transparent;padding:0 18px}
.feed{padding-top:2px}
.club-panel .empty{padding:32px 0;text-align:left}
.club-panel .empty h2{font-size:18px;font-weight:400;line-height:1.5;letter-spacing:0;color:#493326}
.club-panel .composer-wrap{margin:12px;padding:7px 9px;border-radius:8px;flex-shrink:0}
#composer{gap:8px;align-items:flex-end}
#message{display:block;flex:1;min-width:0;min-height:32px;max-height:120px;height:32px;padding:6px 0;font-size:16px;line-height:20px}
.send{width:32px;height:32px;padding:7px;border-radius:6px;display:grid;place-items:center}
.send svg{width:18px;height:18px}
.composer-status:empty{display:none}
.typing-line:has(#typing.active),.typing-line:has(#slowmode:not(:empty)){height:22px}
.message{padding:17px 0 13px}
.message-text{font-size:16px;line-height:1.5}
.message-head{column-gap:6px;row-gap:3px;margin-bottom:7px}
.wallet{font-size:12px}.message-time{font-size:11px}
