/* Shared visual language for the authenticated club. */
.club-connected {
  --ink: #1d1d1f;
  --room-secondary: rgb(29 29 31 / .84);
  --room-line: rgb(29 29 31 / .16);
  --room-divider: rgb(29 29 31 / .1);
  --room-hover: rgb(29 29 31 / .055);
  --room-paper: #fff2d8;
  --line: var(--room-line);
  --ease: cubic-bezier(.22,1,.36,1);
  font-family: -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
  color: var(--ink);
}
body.club-connected .club-shell { max-width: 1360px; padding: 24px 28px 28px; }
.club-connected .club-header:has(#club-title:not([hidden])) { grid-template-columns: minmax(0,1fr) auto minmax(0,1fr); gap: 16px; }
.club-connected .club-brand { gap: 5px; }
.club-connected .club-brand .home svg { width: 142px; height: 142px; }
.club-connected .club-header h1 { font-size: 64px; font-weight: 600; letter-spacing: -2.4px; }
.club-connected .club-header #account { margin: 0; min-height: 36px; max-width: none; padding: 7px 12px; border: 1px solid var(--room-line); border-radius: 999px; background: rgb(255 242 216 / .12); font-size: 12px; line-height: 20px; white-space: nowrap; }
.club-connected .account-controls { grid-column: 3; align-self: start; margin-top: 28px; }
.club-connected .club-header #account:hover { background: rgb(255 242 216 / .18); opacity: 1; }
.club-connected .club-panels { gap: 20px; }
.club-connected .club-panel { border: 1px solid var(--room-line); border-radius: 16px; background: var(--room-paper); box-shadow: 0 3px 14px rgb(29 29 31 / .035); }
.club-connected .panel-heading { height: 56px; min-height: 56px; padding: 0 16px; border-color: var(--room-divider); background: rgb(255 242 216 / .035); }
.club-connected .panel-heading h2 { font-size: 18px; font-weight: 600; letter-spacing: -.35px; }
.club-connected .panel-heading :is(.panel-add,.mentions-button,.vote-help) { display: flex; align-items: center; justify-content: center; width: 32px; height: 32px; min-height: 32px; padding: 0; border: 0; border-radius: 8px; color: var(--room-secondary); }
.club-connected .panel-heading :is(.panel-add,.mentions-button,.vote-help):hover:not(:disabled) { background: var(--room-hover); color: var(--ink); opacity: 1; }
.club-connected .panel-add { font-size: 24px; font-weight: 400; }
.club-connected .mentions-button { font-size: 19px; }
.club-connected .mentions-button svg { width: 20px; height: 20px; }
.club-connected .mentions-button { position: relative; }
.club-connected #mention-count { position: absolute; top: -2px; right: -5px; min-width: 16px; height: 16px; padding: 0 4px; display: grid; place-items: center; border: 2px solid var(--room-paper); border-radius: 999px; background: #b92d30; color: #fff; font-size: 9px; font-weight: 600; line-height: 12px; }
.club-connected #mention-count[hidden] { display: none; }
.club-connected .vote-help { font-size: 15px; }
.club-connected #idea-sort { width: 104px; padding: 8px 0 8px 4px; border-radius: 8px; color: var(--room-secondary); font-size: 12px; letter-spacing: -.15px; }
.club-connected .unread-count { color: var(--room-secondary); }
.club-connected .unread-count::before { display: none; }
.club-connected :is(.feed,.panel-content) { padding: 4px 16px 0; scrollbar-color: rgb(29 29 31 / .2) transparent; scrollbar-width: thin; scrollbar-gutter: stable; }
.club-connected .feed { display: flex; flex-direction: column; padding: 6px 10px; transition: padding-bottom .28s var(--ease); }
.club-connected .feed #messages { flex: none; margin-top: auto; }
.club-connected .feed .older { flex: none; align-self: center; }
.club-connected .chat-panel:has(.typing-bubble.active) .feed { padding-bottom: 38px; }
.club-connected .message { position: relative; width: fit-content; max-width: calc(100% - 12px); margin: 0 auto 5px 0; padding: 7px 8px; border: 0; border-radius: 12px 12px 12px 4px; }
.club-connected .message:last-child { margin-bottom: 0; }
.club-connected .message.message-own { margin-left: auto; margin-right: 0; border-radius: 12px 12px 4px 12px; background: rgb(29 29 31 / .045); }
.club-connected .message-own .message-bar { flex-direction: row-reverse; }
.club-connected .message-own .message-head { justify-content: flex-end; }
.club-connected .message-bar { margin-bottom: 3px; gap: 5px; }
.club-connected .message-text { color: var(--ink); font-size: 15px; line-height: 1.5; letter-spacing: -.12px; }
.club-connected .wallet { color: var(--ink); font-weight: 700; }
.club-connected .message-head .wallet { font-size: 14px; font-weight: 700; letter-spacing: 0; }
.club-connected .message-bar .message-time { color: var(--room-secondary); font-size: 10.5px; opacity: 1; }
.club-connected .badge { padding: 3px 5px; border-color: var(--room-line); border-radius: 5px; font-size: 10px; color: var(--room-secondary); }
.club-connected .agent-badge { background: var(--ink); color: var(--paper); border-color: var(--ink); }
