.club-connected .slowmode-note { flex: none; color: var(--room-secondary); font-size: 10px; font-variant-numeric: tabular-nums; }
.slowmode-note:empty { display: none; }
.pending-state { margin-left: auto; color: var(--room-secondary); font-size: 10px; line-height: 20px; white-space: nowrap; }
.club-connected .reply-draft { font-size: 12px; color: var(--room-secondary); }
