.club-connected .solid { padding: 11px 16px; border-radius: 10px; background: var(--ink); color: var(--paper); font-size: 14px; font-weight: 500; }
.club-connected .solid:hover:not(:disabled) { background: #343437; }
.club-connected .send { display: grid; place-items: center; width: 28px; height: 28px; min-height: 28px; padding: 6px; border-radius: 8px; }
.club-connected .send svg { width: 16px; height: 16px; }
.club-connected .send:disabled { opacity: 1; background: rgb(29 29 31 / .1); color: rgb(29 29 31 / .36); }
.club-connected .composer-status { color: var(--room-secondary); }
.club-connected .new-messages { padding: 0 10px; border-radius: 999px; font-size: 11px; box-shadow: 0 3px 12px rgb(29 29 31 / .12); }
.club-connected :is(.idea-card,.poll-card) { padding: 16px 0; border-color: var(--room-divider); }
.club-connected :is(.idea-card,.poll-card) h3 { margin: 8px 0; font-size: 18px; font-weight: 600; letter-spacing: -.35px; line-height: 1.35; }
.club-connected :is(.idea-preview,.poll-description) { color: var(--ink); font-size: 14px; line-height: 1.55; }
.club-connected .card-meta { color: var(--room-secondary); font-size: 11px; line-height: 1.4; }
.club-connected .status-tag { font-size: 10px; font-weight: 500; letter-spacing: .55px; }
.club-connected .card-actions { gap: 12px; margin-top: 8px; }
.club-connected .card-actions .heart-button { min-height: 28px; font-size: 12px; }
.club-connected .read-more { color: var(--room-secondary); font-size: 12px; text-underline-offset: 3px; }
.club-connected .read-more:hover { color: var(--ink); }
.club-connected .poll-options { gap: 8px; margin-top: 16px; }
.club-connected .poll-option { min-height: 44px; padding: 11px 12px; border-color: var(--room-line); border-radius: 9px; background: rgb(255 242 216 / .04); color: var(--ink); font-size: 14px; line-height: 20px; font-variant-numeric: tabular-nums; }
.club-connected .poll-option::before { background: rgb(29 29 31 / .065); transition: width .45s var(--ease); }
.club-connected .poll-option:hover:not(:disabled) { background: rgb(255 242 216 / .16); border-color: rgb(29 29 31 / .3); }
.club-connected .poll-option[aria-pressed=true] { background: rgb(255 242 216 / .16); border-color: rgb(29 29 31 / .55); }
.club-connected .poll-note { color: var(--room-secondary); font-size: 12px; line-height: 1.5; }
.club-connected .club-panel .empty { padding: 28px 0; }
.club-connected .club-panel .empty h2 { color: var(--room-secondary); font-size: 15px; font-weight: 400; }
.club-connected :is(.reaction-picker,.mention-suggestions) { border: 1px solid var(--room-line); border-radius: 14px; background: var(--paper); box-shadow: 0 10px 32px rgb(29 29 31 / .16); }
.club-connected .reaction-picker button { width: 36px; height: 36px; border-radius: 8px; }
.club-connected .reaction-picker button:hover { transform: translateY(-1px); background: var(--room-hover); }
.club-connected .mention-suggestions>button { border-radius: 8px; }
.club-connected dialog { padding: 24px; border: 1px solid var(--room-line); border-radius: 18px; color: var(--ink); box-shadow: 0 20px 64px rgb(29 29 31 / .2); }
.club-connected dialog::backdrop { background: rgb(29 29 31 / .22); backdrop-filter: blur(8px); }
.club-connected .dialog-head { margin-bottom: 20px; }
.club-connected .dialog-head h2 { font-size: 23px; font-weight: 600; letter-spacing: -.5px; }
.club-connected .dialog-head .icon { display: grid; place-items: center; width: 32px; height: 32px; min-height: 32px; border-radius: 50%; color: var(--room-secondary); background: var(--room-hover); font-size: 22px; line-height: 1; }
.club-connected .form-field { gap: 7px; font-size: 13px; }
.club-connected .form-field :is(input,select,textarea) { padding: 11px 12px; border: 1px solid var(--room-line); border-radius: 9px; background: rgb(255 255 255 / .36); color: var(--ink); font-size: 15px; }
.club-connected .form-field :is(input,select,textarea):focus { border-color: rgb(29 29 31 / .4); box-shadow: 0 0 0 3px rgb(29 29 31 / .055); background: rgb(255 255 255 / .48); }
.club-connected :is(.form-copy,.member-row small,.mention-item time) { color: var(--room-secondary); }
.club-connected .idea-reader>.rich-text { color: var(--ink); font-size: 15px; line-height: 1.6; }
.club-connected :is(button,a,select):focus-visible { outline: 2px solid rgb(29 29 31 / .65); outline-offset: 3px; }
.club-connected :is(button,a) { transition: background .18s,color .18s,border-color .18s,opacity .18s,transform .24s var(--ease); }
.club-connected .message.fresh { animation: member-message-in .42s var(--ease) both; }
.club-online { margin: 0; min-height: 20px; color: var(--room-secondary); font-size: 12px; line-height: 20px; font-variant-numeric: tabular-nums; }
.panel-heading .club-online { display: inline-flex; align-items: center; gap: 6px; font-size: 11px; white-space: nowrap; }
.panel-heading .club-online::before { content: ''; flex: none; width: 6px; height: 6px; border-radius: 50%; background: #238636; }
.club-connected #account,.club-connected .wallet { display: inline-flex; align-items: center; gap: 6px; }
.member-avatar { width: 24px; height: 24px; flex: none; object-fit: cover; border-radius: 50%; }
.club-connected .wallet:has(.member-avatar)::before { display: none; }
.club-connected #account .member-avatar { width: 21px; height: 21px; }
.club-connected .member-welcome { display: flex; align-items: flex-start; gap: 16px; max-width: 680px; margin: 12px auto 4px; padding: 16px 18px; border: 1px solid var(--room-line); border-radius: 14px; background: rgb(255 242 216 / .12); }
.member-welcome h2 { margin: 0 0 7px; font-size: 17px; font-weight: 600; letter-spacing: -.3px; }
.member-welcome p { margin: 0; font-size: 14px; line-height: 1.5; }
.club-connected .welcome-dismiss { width: 28px; height: 28px; min-height: 28px; padding: 0; flex: none; border-radius: 50%; font-size: 21px; color: var(--room-secondary); }
.welcome-topic { text-align: left; text-decoration: underline; text-underline-offset: 3px; margin-top: 8px; font-size: 13px; }
.club-tabs { display: none; }
.club-connected .status-button { color: var(--room-secondary); min-height: 28px; padding: 3px 0 3px 6px; text-underline-offset: 3px; }
.club-connected .status-button:hover { text-decoration: underline; }
.idea-progress { display: grid; grid-template-columns: repeat(4,1fr); list-style: none; padding: 0; margin: 24px 0 18px; }
.idea-progress li { position: relative; display: flex; align-items: center; flex-direction: column; gap: 8px; color: var(--room-secondary); font-size: 11px; }
.idea-progress li:not(:last-child)::after { content: ''; height: 1px; background: var(--room-line); position: absolute; top: 5px; left: calc(50% + 8px); width: calc(100% - 16px); }
.progress-dot { width: 11px; height: 11px; border: 1px solid var(--room-line); border-radius: 50%; }
.idea-progress .recorded .progress-dot { background: var(--ink); border-color: var(--ink); }
.idea-progress .current { color: var(--ink); font-weight: 600; }
.idea-progress .current .progress-dot { outline: 3px solid rgb(29 29 31 / .1); outline-offset: 2px; }
.progress-note { font-size: 14px; line-height: 1.5; }
.result-link { color: var(--ink); font-size: 13px; text-decoration: underline; text-underline-offset: 3px; }
.progress-history { list-style: none; padding: 0; margin: 20px 0; border-top: 1px solid var(--room-divider); }
.progress-history li { padding: 12px 0; border-bottom: 1px solid var(--room-divider); }
.progress-history li>div { display: flex; justify-content: space-between; gap: 12px; align-items: baseline; font-size: 12px; }
.progress-history time { color: var(--room-secondary); font-size: 10px; text-align: right; }
.progress-history p { margin: 6px 0 0; font-size: 13px; line-height: 1.5; }
.avatar-grid { display: grid; grid-template-columns: repeat(4,minmax(0,1fr)); gap: 10px; max-height: 48dvh; overflow: auto; padding: 3px; }
.club-connected .avatar-choice { padding: 8px; border: 1px solid var(--room-line); border-radius: 12px; display: flex; flex-direction: column; gap: 7px; align-items: center; font-size: 12px; }
.club-connected .avatar-choice[aria-pressed=true] { border-color: var(--ink); background: var(--room-hover); }
.avatar-preview,.avatar-none { width: 100%; height: auto; aspect-ratio: 1; border-radius: 8px; object-fit: cover; }
.avatar-none { display: grid; place-items: center; background: var(--room-hover); font-size: 22px; }
@media(hover:hover) and (pointer:fine) {
  .club-connected .message .message-actions { opacity: 0; pointer-events: none; transform: translateY(3px); }
  .club-connected .message:hover .message-actions,.club-connected .message:focus-within .message-actions,.club-connected .message:has([aria-expanded=true]) .message-actions { opacity: 1; pointer-events: auto; transform: none; }
}
@keyframes member-message-in { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
@media(prefers-reduced-motion:reduce) {
  .club-connected .message.fresh { animation: none; }
  .club-connected .message-actions { transition: none; }
  .typing-bubble { transition: none; }
}
@media(max-width:1000px) {
  body.club-connected .club-shell { max-width: 760px; padding: 20px 24px 24px; }
  .club-connected .club-tabs { position: relative; isolation: isolate; display: grid; grid-template-columns: repeat(3,1fr); gap: 4px; margin: 16px 0 0; padding: 4px; border: 1px solid var(--room-line); border-radius: 12px; background: rgb(29 29 31 / .045); }
  .club-tabs::before { content: ''; position: absolute; z-index: -1; top: 4px; bottom: 4px; height: auto; left: 4px; width: calc((100% - 16px)/3); background: rgb(255 242 216 / .64); border-radius: 8px; box-shadow: 0 1px 3px rgb(29 29 31 / .08); transform: translateX(calc(var(--tab-index,0)* (100% + 4px))); transition: transform .3s var(--ease); }
  .club-connected .club-tabs button { padding: 9px 4px; min-height: 38px; font-size: 14px; color: var(--room-secondary); border-radius: 8px; }
  .club-connected .club-tabs button[aria-selected=true] { color: var(--ink); font-weight: 600; }
  .club-connected .club-panels { margin-top: 12px; }
  .club-connected .club-panel { height: clamp(440px,calc(100dvh - 244px),650px); }
}
@media(max-width:600px) {
  body.club-connected .club-shell { padding: 18px 14px 24px; }
  .club-connected .club-header:has(#club-title:not([hidden])) { grid-template-columns: minmax(0,1fr); gap: 12px; }
  .club-connected .club-brand { grid-column: 1; }
  .club-connected .club-brand .home svg { width: 112px; height: 112px; }
  .club-connected .club-header h1 { font-size: 48px; letter-spacing: -1.7px; }
  .club-connected .account-controls { grid-column: 1; justify-self: center; margin-top: 0; }
  .club-connected .club-header #account { padding: 6px 11px; font-size: 12px; }
  .club-connected .club-panels { gap: 16px; }
  .club-connected .panel-heading { padding: 0 14px; }
  .club-connected :is(.feed,.panel-content) { padding-left: 14px; padding-right: 14px; }
  .club-connected .club-panel .composer-wrap { margin: 6px 10px 10px; }
  .club-connected dialog { padding: 22px; }
  .avatar-grid { grid-template-columns: repeat(3,minmax(0,1fr)); }
}

/* Conversation actions stay with the thought they belong to. */
.club-connected .message.continued{border-top:0;padding-top:5px}
.club-connected .message.continued .message-head{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}
.club-connected .message.continued .message-bar{float:right;margin:0 0 0 8px;min-height:0}
.club-connected .message-time{opacity:.55;font-size:10px}
.club-connected .message:hover .message-time,.club-connected .message:focus-within .message-time{opacity:1}
.message-links{display:grid;gap:7px;margin-top:9px}
.suggestion-card,.linked-card{border:1px solid var(--club-border,rgba(0,0,0,.12));border-radius:10px;background:rgba(255,242,216,.16);padding:11px 12px;text-align:left}
.suggestion-card strong{font-size:13px;line-height:1.4;display:block}
.suggestion-actions{display:flex;align-items:center;gap:12px;margin-top:9px}
.club-connected .suggestion-actions button{min-height:30px;padding:4px 10px;font-size:12px}
.suggestion-caption,.linked-kind{font-size:10px;opacity:.65}
.suggestion-caption{display:block;margin-top:5px}
.club-connected .linked-card{display:flex;flex-direction:column;align-items:flex-start;gap:3px;width:100%;font-size:12px;line-height:1.4}
.club-pins{padding:7px 12px;border-bottom:1px solid rgba(0,0,0,.08);display:grid;gap:5px}
.club-pins[hidden]{display:none}
.club-connected .club-pins button{display:flex;gap:9px;width:100%;padding:4px 0;min-height:0;font-size:11px;text-align:left;background:transparent;border:0}
.club-pins button span:first-child{opacity:.6;flex-shrink:0}
.club-pins button span:last-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.host-history{display:grid;gap:16px}
.host-history article{border-bottom:1px solid rgba(0,0,0,.1);padding-bottom:14px}
.host-history article>div{display:flex;justify-content:space-between;gap:10px;font-size:12px}
.host-history strong{text-transform:capitalize}
.host-history p{font-size:13px;line-height:1.5;margin:6px 0}
.host-history time,.host-reversed{font-size:10px;opacity:.6;margin-right:10px}
.tab-count{display:inline-grid;place-items:center;min-width:16px;height:16px;padding:0 3px;border-radius:8px;background:rgba(0,0,0,.08);font-size:10px;margin-left:5px}
.tab-count[hidden]{display:none}
@media(prefers-reduced-motion:no-preference){.message-time{transition:opacity .18s ease}.linked-card{transition:background .18s ease,transform .18s ease}.linked-card:hover{background:rgba(255,242,216,.26)}.linked-card:active{transform:scale(.985)}}

.idea-research:empty{display:none}.idea-research{display:grid;gap:10px;padding:16px 0;border-top:1px solid currentColor;margin-top:16px}.idea-research p{margin:0;line-height:1.5}.idea-research time{font-size:11px;opacity:.6}.idea-research a{width:fit-content;text-underline-offset:3px}.idea-research button{justify-self:start}

/* Operational details stay within the signed-in experience. */
.club-connected .idea-latest-note{font-size:12px;line-height:1.5;opacity:.72;margin:8px 0 0;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.club-health-row{display:flex;justify-content:space-between;align-items:baseline;gap:24px;padding:12px 0;border-bottom:1px solid rgba(23,19,15,.12);font-size:14px}
.club-health-row strong{text-align:right;font-weight:500}
@media(max-width:480px){.club-health-row{gap:12px;font-size:12px}}

/* Connected identities share the same typography as club names. */
.account-controls{display:flex;align-items:center;justify-content:flex-end;gap:12px;min-width:0}
.account-x{font-size:14px;line-height:36px;color:inherit;text-decoration:none;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:160px}
.x-profile,.profile-x-name{color:inherit;text-decoration:none;text-underline-offset:3px}
.x-profile:hover,.account-x:hover,.profile-x-name:hover{text-decoration:underline}
.member-manage{display:inline-grid;place-items:center;width:22px;height:22px;padding:0;border:0;background:none;color:inherit;font-size:17px;opacity:.5;transition:opacity .18s}
.member-manage:hover,.member-manage:focus-visible{opacity:1}
.profile-social{display:grid;gap:10px;padding-bottom:18px;margin-bottom:4px;border-bottom:1px solid rgba(23,19,15,.12)}
.profile-x-name{font-size:20px;justify-self:center;margin-bottom:6px}
