/* Three equal rooms: updates, conversation and member decisions. */
.club-connected .community-panel{padding:0;overflow:hidden;display:flex;flex-direction:column}
.community-heading{flex:none}
.community-tabs{grid-column:2;grid-row:1;display:grid;grid-template-columns:1fr 1fr;position:relative;isolation:isolate;gap:2px;padding:3px;border-radius:9px;background:rgb(29 29 31 / .045)}
.community-tabs::before{content:'';position:absolute;z-index:-1;top:3px;bottom:3px;left:3px;width:calc((100% - 8px)/2);border-radius:6px;background:rgb(255 255 255 / .7);box-shadow:0 1px 3px rgb(29 29 31 / .06);transform:translateX(calc(var(--choice-index,0)*(100% + 2px)));transition:transform .28s var(--ease)}
.community-tabs button{padding:7px 10px;min-height:32px;border-radius:6px;font-size:14px;font-weight:500;color:var(--room-secondary);white-space:nowrap}
