.community-tabs .tab-count{font-size:9px;margin-left:3px}
.club-connected .community-heading{gap:5px;padding:0 12px}
.club-connected .community-heading #idea-sort{width:81px;font-size:11px}
.community-view{display:flex;flex:1;min-height:0;overflow:hidden;flex-direction:column}
