.update-meta>span{font-weight:600}
.update-meta>time{margin-left:auto}
.club-update h3{font-size:16px;line-height:1.45;font-weight:600;letter-spacing:-.25px;margin:8px 0 7px}
.club-update .update-body{font-size:14px;line-height:1.6;letter-spacing:-.1px}
.update-remove{display:grid;place-items:center;width:24px;height:24px;flex:none;margin:-4px -4px -4px 0;padding:4px;border-radius:6px;color:var(--room-secondary);opacity:.6}
.update-remove svg{width:16px;height:16px}
.update-remove:hover{background:var(--room-hover);opacity:1}
.club-connected .message.message-own{max-width:88%;padding:8px 11px 9px;border:1px solid rgb(29 29 31 / .065);border-radius:13px 13px 4px 13px;background:rgb(255 255 255 / .58);box-shadow:0 1px 2px rgb(29 29 31 / .025)}
.club-connected .message-own .message-bar{position:relative;flex-direction:row;justify-content:flex-end;min-height:12px;margin-bottom:3px}
.club-connected .message-own .own-head{flex:none;min-height:12px;line-height:12px}
.club-connected .message-own .message-time{font-size:9px;line-height:12px;opacity:.58;margin:0}
.club-connected .message-own .message-text{text-align:left}
.club-connected .message.continued:not(.message-own) .message-bar{float:none;margin:0 0 3px;justify-content:flex-end}
.club-connected .message-own .reactions:not(:empty){margin-top:7px;justify-content:flex-end}
.club-connected .message-own.continued .message-bar{position:relative;float:none;margin:0 0 3px;min-height:12px}
.club-connected .message-own.continued .own-head{position:static;clip-path:none;width:auto;height:auto;overflow:visible}
.club-connected .message-own .pending-state{font-size:9px;line-height:12px;margin-left:7px}
@media(hover:hover) and (pointer:fine){
 .club-connected .message.continued:not(.message-own) .message-bar{position:absolute;left:0;bottom:calc(100% - 2px);margin:0}
 .club-connected .message.continued:not(.message-own) .message-actions{padding:2px 4px;border:1px solid var(--room-line);border-radius:9px;background:var(--room-paper);box-shadow:0 4px 12px rgb(29 29 31 / .08)}
 .club-connected .message-own .message-actions{position:absolute;z-index:3;right:-5px;bottom:calc(100% + 8px);padding:2px 4px;border:1px solid var(--room-line);border-radius:9px;background:var(--room-paper);box-shadow:0 4px 12px rgb(29 29 31 / .08)}
 .club-connected .message-own .message-actions::after{content:'';position:absolute;top:100%;left:0;right:0;height:12px}
}
@media(prefers-reduced-motion:reduce){.community-tabs::before{transition:none}}
@media(max-width:1150px){
 .community-tabs button{padding-left:7px;padding-right:7px;font-size:13px}
 .club-connected .community-heading #idea-sort{width:70px;font-size:10px}
}

.club-connected .club-brand>.club-online{display:block;margin-top:6px;font-size:12px;line-height:20px;color:var(--ink);opacity:.72;text-align:center}
.club-connected #polls,.club-connected #topics-list,.club-connected #update-feed{display:flex;flex-direction:column;gap:12px;padding:12px 14px 16px}
.club-connected :is(.poll-card,.topic-card,.club-update){flex:none;margin:0;padding:14px;border:1px solid var(--room-line);border-radius:12px;background:rgb(255 255 255 / .28);box-shadow:0 1px 2px rgb(29 29 31 / .025)}
.club-connected .poll-card h3{font-size:16px;line-height:1.45;margin:7px 0}
.club-connected .poll-description{font-size:13px;line-height:1.55;margin:6px 0}
.club-connected .poll-thumbs{display:flex;gap:8px;margin-top:12px}
.club-connected .poll-thumbs .poll-option{display:flex;align-items:center;justify-content:center;gap:8px;min-width:70px;min-height:38px;padding:7px 10px;border:1px solid var(--room-line);background:rgb(255 255 255 / .35);border-radius:9px;font-size:12px}
.club-connected .poll-thumbs .poll-option::before{display:none}
.club-connected .poll-thumbs .poll-option[aria-pressed=true]{border-color:rgb(29 29 31 / .35);background:rgb(255 255 255 / .65)}
.club-connected .vote-symbol{font-size:18px;line-height:22px}
.club-connected .vote-count{font-size:12px;font-variant-numeric:tabular-nums}
.club-connected :is(.poll-close,.poll-details){display:block;font-size:11px;line-height:1.5;padding:3px 0;min-height:0;margin-top:8px;color:var(--room-secondary);text-decoration:underline;text-underline-offset:3px}

.club-connected .message-bar .agent-name::before{display:none}

