.topic-toolbar h3{font-size:14px;line-height:1.4;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.topic-toolbar button{display:grid;place-items:center;width:28px;height:28px;border-radius:7px;font-size:22px;line-height:1}
