.topic-card-heading{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:15px;line-height:1.4;transition:opacity .2s}
.topic-card-heading strong{flex:1;min-width:0;font-weight:600;overflow-wrap:anywhere}
.topic-card-heading::after{content:'';flex:none;width:6px;height:6px;margin:0 3px;border-top:1.5px solid currentColor;border-right:1.5px solid currentColor;transform:rotate(45deg);opacity:.55}
.topic-preview{font-size:13px;line-height:1.5;color:var(--room-secondary);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}
