.topic-unread{display:grid;place-items:center;flex:none;min-width:18px;height:18px;padding:0 5px;border-radius:9px;background:var(--ink);color:var(--paper);font-size:9px}
.topics-list .empty p{font-size:13px;color:var(--room-secondary);line-height:1.6}
.topics-more{display:block;margin:8px auto}
.message-topic{display:inline-flex;align-items:center;gap:7px;max-width:100%;min-height:30px;margin-top:9px;padding:5px 9px;border:1px solid var(--room-line);border-radius:8px;background:rgb(255 255 255 / .38);font-size:11px;font-weight:500;line-height:18px;text-decoration:none;color:var(--ink);transition:background .2s var(--ease),border-color .2s var(--ease)}
.message-topic svg{width:14px;height:14px;flex:none}
