body[data-ui=club].club-connected .club-panels{margin-top:8px;gap:16px}
body[data-ui=club].club-connected .club-panel{border-radius:18px}
body[data-ui=club].club-connected .panel-heading{height:60px;min-height:60px;padding:0 12px}
