styles.2608ac6766c26b01fe34:
/* CLAUS interface primitives. Loaded last by every interactive page. */
@font-face{font-family:Claus UI;src:url("archive-asset:59467fa0151050b34dc1") format('woff2');font-weight:200 800;font-display:swap}
:root{--ui-orange:#ec673a;--ui-canvas:radial-gradient(ellipse at 48% 41%,#f68859 0%,#ee7144 39%,#e96436 78%);--ui-paper:#fff2d8;--ui-ink:#11110e;--ui-muted:#5c5143;--ui-line:#11110e26;--ui-radius:20px;--ui-ease:cubic-bezier(.22,1,.36,1);--ui-title:clamp(32px,4vw,52px);--ui-footer:clamp(180px,calc(100dvh - 420px),300px);--paper:var(--ui-paper);--orange:var(--ui-orange);--ink:var(--ui-ink)}
html:has(body[data-ui]){height:100%;overflow:hidden;overscroll-scrollbar-gutter:auto}
body[data-ui]{width:100%;height:100dvh;min-height:0;max-height:100dvh;margin:0;overflow:hidden;overscroll-background:var(--ui-canvas);isolation:isolate;color:var(--ui-ink);font-family:Claus UI,Arial,sans-serif;font-optical-sizing:auto;-webkit-font-smoothing:antialiased}
body[data-ui] :is(button,input,textarea,select){font-family:inherit}
body[data-ui] :is(h1,h2,h3){text-wrap:balance}
body[data-ui] :is(input,textarea){font-size:16px}
body[data-ui] :is(button,a){-webkit-tap-highlight-color:transparent;touch-action:manipulation}
body[data-ui] :is(button,a):focus-visible{outline:2px solid currentColor;outline-offset:4px}
body[data-ui] :is(dialog,[popover]){background:var(--ui-paper);color:var(--ui-ink);border:1px solid var(--ui-line);border-radius:var(--ui-radius);box-shadow:0 18px 64px #0002;font-family:inherit;overscroll-padding:28px;font-size:17px;line-height:1.5}
body[data-ui] dialog h2{font-size:28px;font-weight:550;line-height:1.2;letter-spacing:-.035em}
body[data-ui] dialog::backdrop{background:#0005;backdrop-filter:blur(5px)}
body[data-ui] :is(.solid,.solid-button,.primary,#enter,#connect){background:var(--ui-ink);color:var(--ui-paper)!important;border:1px solid var(--ui-ink);border-radius:12px;min-height:46px;padding:12px 22px;font-size:17px;font-weight:500;line-height:1.3}
body[data-ui] :is(.solid,.solid-button,.primary,#enter,#connect):active:not(:disabled){scale:.96}
body[data-ui] :is(.wallet-options button,.dialog-stack>button){min-height:52px;border:1px solid var(--ui-line);border-radius:12px;padding:12px 16px;font-size:17px;background:transparent;color:var(--ui-ink);gap:14px}
body[data-ui] :is(.wallet-options button,.dialog-stack>button):hover{background:#00000006}
body[data-ui] :is(.metric-number,.personal-reward-amount,.stats strong,.pool-stats strong,.nft-stat strong,.nft-reward-stat strong){font-variant-numeric:tabular-nums;letter-spacing:-.035em;line-height:1.2;overflow-wrap:normal}
body[data-ui] :is(.stats section,.pool-stats>div,.nft-reward-stat,.personal-reward-metric,.personal-reward-history,.project-item,.project-form){background:var(--ui-paper);border:1px solid var(--ui-line);border-radius:var(--ui-radius);box-shadow:none}
body[data-ui] :is(.feed,.panel-content,.claus-page-body,.ui-scroll){overscroll-scrollbar-width:thin;scrollbar-color:#1113 transparent;overflow-anchor:none}

/* The canvas stays still. Only a bounded content pane can scroll. */
body[data-ui]:not([data-ui=site]):not([data-ui=club]){display:flex;flex-direction:column;padding:0;max-width:none}
body[data-ui]:not([data-ui=site]):not([data-ui=club])>header{flex:none;min-height:76px;width:min(100%,1180px);margin:0 auto;padding:12px 28px;gap:16px}
body[data-ui]:not([data-ui=site]):not([data-ui=club])>main{flex:1 1 0;min-height:0;width:min(100%,1080px);max-width:1080px;margin:0 auto;padding:16px 28px 28px;overflow:auto;overscroll-scrollbar-width:thin;scrollbar-color:#1113 transparent;overflow-anchor:none}
body[data-ui]:not([data-ui=site]):not([data-ui=club])>footer:not(.club-footer){flex:none;min-height:52px;margin:0;padding:8px 24px;display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:8px 24px;font-size:15px}
body[data-ui] :is(.nft-title h1,.dashboard-heading h1,.builder-intro h1,.atlas-heading h1,.hero h1,.arena-heading h1,.privacy-title h1){font-size:var(--ui-title);font-weight:550;letter-spacing:-.045em;line-height:1.1;text-align:center}
body[data-ui] .club-footer{--claus-footer-height:var(--ui-footer);height:var(--ui-footer);min-height:var(--ui-footer);margin:0;flex:none;contain:layout}
body[data-ui] .club-footer-claus{height:calc(var(--ui-footer) + 30px)}
body[data-ui] .claus-socials{gap:20px;bottom:max(12px,env(safe-area-inset-bottom));align-items:center}

/* Home: one centered tree with a quiet, short introduction. */
body[data-ui=site] #stage{height:100dvh}
body[data-ui=site] #stage[data-page=home] .claus-home{inset:20px 20px 110px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:24px;padding:0;overflow:hidden;--copy-size:18px;--copy-leading:1.45}
