/* First show the work and its outcome; the map explains the machinery below. */
.work-now{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr;gap:28px;min-width:0}
.work-now>article{min-width:0;padding:24px 26px;border:1px solid var(--ink);border-radius:6px;display:flex;flex-direction:column;align-items:flex-start}
.work-eyebrow{font-size:12px;font-weight:550;margin-bottom:14px!important}
.work-now h2{font-size:clamp(23px,2.2vw,30px);line-height:1.17;letter-spacing:-.03em;margin-bottom:14px;max-width:28ch;overflow-wrap:anywhere;text-wrap:pretty}
.work-now h2 a:hover{text-decoration:underline;text-underline-offset:4px}
.work-now p:not(.work-eyebrow):not(.note-meta){font-size:16px;line-height:1.55;max-width:62ch}
.work-now .note-meta{margin-top:14px}
.work-now .atlas-text-button{font-size:14px!important;margin-top:auto;padding-top:14px;text-decoration:underline;text-underline-offset:4px}
.topic-filters{display:flex;flex-wrap:wrap;gap:8px;margin:4px 0 18px}
.topic-filters button{border:1px solid var(--rule);border-radius:4px;background:none;min-height:40px;padding:8px 12px;font-size:13px}
.topic-filters button[aria-pressed=true]{background:var(--ink);color:var(--orange);border-color:var(--ink)}
.activity-grouped{display:block;font-size:10px;line-height:1.5;color:var(--muted);margin-top:8px}
.dialog-original{margin:0;font-size:14px;line-height:1.6;white-space:pre-line;overflow-wrap:anywhere}
.dialog-section .note-meta{font-size:12px;margin-top:10px}
@media(max-width:1100px){.work-now{gap:20px}.work-stream{order:1}.architecture{order:2}.work-now{order:0}}
@media(max-width:640px){.work-now{grid-template-columns:1fr;gap:16px}.work-now>article{padding:20px}.work-now h2{font-size:25px}.work-now p:not(.work-eyebrow):not(.note-meta){font-size:16px}.work-now .atlas-text-button{min-height:44px}}
.work-meta{display:flex;gap:6px 14px;flex-wrap:wrap;margin-top:16px!important;font-size:12px!important;color:var(--muted)}
.work-now .atlas-text-button{display:inline-flex;align-items:center;gap:8px}
.work-now .atlas-text-button .atlas-icon{width:16px;height:16px}
.work-summary{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:3;overflow:hidden}

