.entry{min-height:calc(100svh - 156px);padding-bottom:40px}.entry button{margin-top:30px}.pool-stats{display:grid;grid-template-columns:1fr 1fr;max-width:660px;margin:28px auto 0;padding:24px 0 10px;border-top:1px solid var(--line);text-align:center;gap:24px}.pool-stats>div+div{border-left:1px solid var(--line)}.pool-stats h2{font-size:13px;margin:0 0 12px}.pool-stats strong{font-weight:500;font-size:clamp(22px,3vw,30px);letter-spacing:-.035em;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.pool-stats p{font-size:12px;opacity:.6;margin:8px 0 0}
@media(max-width:600px){.entry{min-height:calc(100svh - 132px);padding-bottom:40px}.pool-stats{gap:14px;margin-top:24px;padding-top:22px}.pool-stats h2{font-size:11px;line-height:1.4}.pool-stats strong{font-size:20px}.pool-stats p{font-size:11px}}

.splash-brand{display:flex;align-items:center;justify-content:center;width:52px;height:52px}
.splash-brand svg{width:52px;height:52px;display:block;fill:#000}
.entry h1{font-size:clamp(58px,8vw,80px)}
.dashboard-heading h1{font-size:clamp(48px,6vw,58px)}
.payout-note{display:flex;justify-content:center;align-items:baseline;gap:7px}
#payout-countdown{font-variant-numeric:tabular-nums;font-weight:600;letter-spacing:.025em}
.tabs{position:relative;gap:0}
.tabs:after{content:'';position:absolute;bottom:-1px;left:0;width:50%;height:2px;background:var(--ink);transition:transform .3s cubic-bezier(.22,.61,.36,1)}
.tabs[data-withdraw=true]:after{transform:translateX(100%)}
.tabs button{flex:1;text-align:center;border-bottom:0;padding:17px 4px 15px;transition:opacity .25s}
.tabs button[aria-selected=true]{border-bottom:0}
.tab-panels{display:grid}
.tab-panels>[role=tabpanel]{grid-area:1/1;align-self:start;opacity:1;visibility:visible;transform:none;transition:opacity .24s ease,transform .28s ease,visibility .24s}
.tab-panels>[role=tabpanel][hidden]{display:block!important;visibility:hidden;opacity:0;pointer-events:none;transform:translateY(5px)}
.wallet-options button{display:flex;align-items:center;gap:14px}
.wallet-options img{display:block;width:28px;height:28px;object-fit:contain}
dialog[open]{animation-duration:.32s;animation-timing-function:cubic-bezier(.22,.61,.36,1)}
@media(prefers-reduced-motion:reduce){.tabs:after,.tab-panels>[role=tabpanel],.tabs button{transition:none}.tab-panels>[role=tabpanel][hidden]{transform:none}}

/* The footer remains below both the entrance and the connected dashboard. */
body>header{width:100%;margin:0 auto;flex:none}
body>main{width:100%;flex:1 0 auto;padding-bottom:24px}
body:has(#entry:not([hidden])){--claus-footer-height:clamp(180px,calc(100dvh - 480px),300px)}
@media(max-width:600px){body:has(#entry:not([hidden])){--claus-footer-height:clamp(180px,calc(100dvh - 520px),270px)}}
main:has(#entry:not([hidden])){display:flex;flex-direction:column;justify-content:center}
#entry{min-height:0;padding:8px 0 20px}
#entry .splash-mark{width:128px;height:160px;margin-bottom:18px}
#entry h1{font-size:clamp(58px,7vw,72px)}
#entry button{margin-top:24px}
@media(max-height:700px){body>header{padding-top:16px;padding-bottom:16px}#entry .splash-mark{width:104px;height:130px;margin-bottom:14px}#entry h1{font-size:58px}#entry button{margin-top:20px}}

.dashboard-heading .splash-character{width:34px;height:44px;min-width:0;min-height:0}

/* Balances remain visible when a wallet is viewing another network. */
.stats{grid-template-columns:repeat(3,minmax(0,1fr))}
.pool-stats{grid-template-columns:repeat(2,minmax(0,1fr))}
.stats section,.pool-stats>div{min-width:0}
/* Reserve both lines before counting: intermediate fractions must not move the footer. */
.stats strong,.pool-stats strong{display:block;min-height:2.6em;line-height:1.3;align-content:center;overflow-wrap:anywhere}
#liquidity-claus{min-height:2.8em;line-height:1.4}
@media(max-width:600px){.stats strong{font-size:16px}}
.eth-label{display:flex;flex-direction:column;gap:6px}.eth-balance{font-size:12px;opacity:.65;font-variant-numeric:tabular-nums}
.network-notice{display:flex;align-items:center;justify-content:center;gap:14px;flex-wrap:wrap;margin:0 auto 20px;font-size:14px;text-align:center}.network-notice button{font-size:13px;padding:8px 13px;min-height:36px}.network-notice[hidden]{display:none}
/* Keep confirmation progress beside the action it belongs to. */
.liquidity-card #status{margin:16px 0 0}.liquidity-card .pending-card{margin:16px 0 0;padding:16px 0 0;border:0;border-top:1px solid var(--line);border-radius:0}.pending-card #pending-text{margin:0;font-weight:500}.pending-card #pending-detail{margin:6px 0 0;font-size:12px;line-height:1.5;opacity:.65}.pending-card #pending-detail:empty{display:none}

styles.fdf13518ab639b2a2130:
/* Personal rewards share the existing NFT/Splash frame and never authorize actions. */
.personal-rewards{margin:28px auto;width:100%;max-width:900px;color:inherit}
.personal-rewards[hidden]{display:none!important}
.personal-rewards .personal-reward-title{text-align:center;font-size:26px;font-weight:500;letter-spacing:-.03em;margin:0 0 20px}
.personal-reward-metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-bottom:16px}
.personal-reward-metric,.personal-reward-history{background:#fff3d611;border:1px solid #1113;border-radius:16px}
.personal-reward-metric{min-width:0;min-height:144px;padding:22px 18px;text-align:center}
.personal-rewards .personal-reward-metric h3{font-size:16px;font-weight:400;margin:0 0 14px}
.personal-reward-amount{display:block;font-size:clamp(24px,3.2vw,34px);font-weight:550;letter-spacing:-.03em;font-variant-numeric:tabular-nums;overflow-wrap:anywhere;line-height:1.25;min-height:1.25em}
.personal-rewards .personal-reward-detail{font-size:14px;line-height:1.5;margin:10px 0 0;opacity:.75;text-align:center;max-width:none}
.personal-reward-history{padding:22px 24px}
.personal-reward-history-top{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:16px}
.personal-rewards .personal-reward-history h3{font-size:20px;line-height:1.3;font-weight:500;margin:0}
.personal-reward-pending{display:flex;gap:10px;align-items:baseline;font-size:14px;text-align:right}
.personal-reward-pending .personal-reward-amount{font-size:17px;white-space:nowrap;letter-spacing:0}
.personal-rewards .personal-reward-payment{display:grid;grid-template-columns:1.1fr 1fr 1fr;gap:12px;align-items:center;min-height:57px;padding:14px 0;border-top:1px solid #1112;color:inherit;text-decoration:none;font-size:16px;line-height:1.4}
.personal-rewards .personal-reward-payment:hover{opacity:.75;text-decoration:none}
.personal-reward-payment{transition:opacity .18s ease}
.personal-reward-payment:focus-visible,.personal-reward-more:focus-visible{outline:2px solid currentColor;outline-offset:4px}
.personal-reward-date{font-size:14px;opacity:.75}.personal-reward-paid{text-align:right;font-size:16px;font-weight:500;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}
.personal-rewards .personal-reward-status{font-size:15px;line-height:1.5;margin:16px 0 0;text-align:center;max-width:none}
.personal-rewards .personal-reward-more{display:block;min-height:44px;margin:14px auto 0;padding:8px 16px;border:1px solid #1113;border-radius:8px;background:transparent;color:inherit;font-size:15px;cursor:pointer}
.personal-rewards [hidden]{display:none!important}
@media(max-width:600px){
 .personal-rewards{margin:24px auto}.personal-reward-metrics{gap:10px}.personal-reward-metric{padding:19px 13px;min-height:138px}
 .personal-reward-history{padding:19px 17px}.personal-reward-history-top{align-items:flex-start;flex-wrap:wrap;gap:12px}
 .personal-reward-pending{width:100%;justify-content:space-between;text-align:left}
 .personal-rewards .personal-reward-payment{grid-template-columns:minmax(0,1fr) minmax(0,1fr);grid-template-areas:"kind amount" "date amount";gap:4px 10px;font-size:15px}
 .personal-reward-kind{grid-area:kind}.personal-reward-date{grid-area:date;font-size:13px}.personal-reward-paid{grid-area:amount;font-size:15px}
}
@media(prefers-reduced-motion:reduce){.personal-reward-payment{transition:none}}

styles.ff388769886eb1fee464:
/* Only these two complete documents opt in. The wallet modules remain isolated. */
@view-transition{navigation:auto}
:root{view-transition-name:none}
.staking-heading{view-transition-name:staking-heading}
.staking-indicator{view-transition-name:staking-indicator}
a[aria-label="Claus home"]{view-transition-name:staking-brand}
.club-footer{view-transition-name:staking-footer}
body>main{view-transition-name:staking-content}
::view-transition{pointer-events:none}
::view-transition-group(staking-heading),::view-transition-group(staking-brand),::view-transition-group(staking-footer){animation-duration:0s}
::view-transition-group(staking-indicator){animation-duration:180ms;animation-timing-function:cubic-bezier(.2,.7,.2,1)}
::view-transition-old(staking-heading),::view-transition-old(staking-brand),::view-transition-old(staking-footer){animation:none;opacity:0}
::view-transition-new(staking-heading),::view-transition-new(staking-brand),::view-transition-new(staking-footer){animation:none}
::view-transition-old(staking-content),::view-transition-new(staking-content){animation-duration:160ms;mix-blend-mode:normal}
@media(prefers-reduced-motion:reduce){@view-transition{navigation:none}::view-transition-group(*){animation-duration:0s}}

styles.6b724c6faf565ee5b224:
/* One shared workspace: a consistent action area followed by public figures. */
body[data-ui].staking-page>main:has(.staking-shell){display:flex;flex-direction:column;align-items:stretch;justify-content:flex-start;gap:0;grid-template-columns:none;grid-template-rows:none;width:min(100%,1120px);max-width:1120px;padding:8px 28px 16px;overflow:auto}
body[data-ui=splash].staking-page>main:has(.staking-shell):has(#entry:not([hidden])){display:flex;justify-content:flex-start;overflow:auto}
.staking-shell{display:flex;flex-direction:column;flex:none;min-width:0;width:100%;background:var(--ui-paper);border:1px solid var(--ui-line);border-radius:24px;overflow:hidden}
.staking-summary{padding:8px 24px 12px}
.staking-overview-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;min-height:44px;margin-bottom:4px}
body[data-ui] .staking-overview-heading h2,body[data-ui] .staking-entry-copy h2{margin:0;font-size:16px;line-height:1.4;font-weight:600;letter-spacing:-.01em}
body[data-ui] .staking-overview-heading button{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;padding:10px 12px;margin:0;border:0;border-radius:10px;box-shadow:none;background:transparent;color:var(--ui-ink);font-size:14px;font-weight:500;line-height:1.4;white-space:nowrap}
.staking-overview-heading button svg{flex:none}
.staking-public{display:grid;grid-template-columns:3fr 2fr;gap:24px;align-items:start;min-width:0}
body[data-ui].staking-page .staking-overview{min-width:0;margin:0;padding:0;border:0}
.staking-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px;margin:0}
.staking-metrics>div{min-width:0}
.staking-metrics dt{margin:0 0 8px;font-size:13px;font-weight:450;line-height:1.4;color:var(--ui-muted)}
.staking-metrics dd{margin:0;font-size:30px;font-weight:550;letter-spacing:-.04em;line-height:1.15;min-height:1.15em;white-space:nowrap;font-variant-numeric:tabular-nums}
.staking-metric-note{display:block;min-height:1.4em;margin-top:4px;font-size:12px;line-height:1.4;color:var(--ui-muted)}
.staking-global-rewards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px;min-width:0;margin:0}
.staking-global-rewards>div{min-width:0}
.staking-global-rewards span{display:block;margin-bottom:8px;font-size:13px;line-height:1.4;color:var(--ui-muted)}
.staking-global-rewards strong{display:block;font-size:22px;font-weight:550;letter-spacing:-.03em;line-height:1.55;white-space:nowrap;font-variant-numeric:tabular-nums}
.staking-stats-feedback{display:flex;align-items:center;gap:12px;font-size:12px;line-height:1.4}
.staking-stats-feedback:has(#staking-stats-status:empty):has(button[hidden]){display:none}
body[data-ui] .staking-stats-feedback button{background:transparent;color:var(--ui-ink);padding:8px;min-height:44px;font-size:13px;text-decoration:underline}
.staking-overview[data-state=stale] .staking-metrics{opacity:.65}

body[data-ui=nfts].staking-page.nft-page .staking-public .nft-rewards{width:100%;max-width:none;margin:0;padding:0;border:0;text-align:start}
body[data-ui=nfts].staking-page.nft-page .staking-public .nft-reward-grid{gap:24px}
body[data-ui=nfts].staking-page.nft-page .staking-public .nft-reward-stat{padding:0;background:transparent;border:0;border-radius:0;box-shadow:none;text-align:start}
body[data-ui=nfts].staking-page.nft-page .staking-public .nft-reward-stat h2{font-size:13px;font-weight:450;line-height:1.4;margin:0 0 8px;color:var(--ui-muted)}
body[data-ui=nfts].staking-page.nft-page .staking-public .nft-reward-stat strong{display:block;min-height:1.15em;margin:0;font-size:30px;font-weight:550;letter-spacing:-.04em;line-height:1.15;white-space:nowrap}
body[data-ui=nfts].staking-page.nft-page .staking-public .nft-reward-stat>span{display:block;min-height:1.4em;margin-top:4px;font-size:12px;line-height:1.4;color:var(--ui-muted)}
body[data-ui=nfts].staking-page.nft-page .staking-public .nft-reward-timing{margin:8px 0 0;font-size:12px;line-height:1.4;color:var(--ui-muted);text-align:start;font-variant-numeric:tabular-nums}
.staking-public .nft-reward-timing p{margin:0}

.staking-personal{min-width:0;padding:8px 24px;border-bottom:1px solid var(--ui-line)}
body[data-ui=nfts].staking-page.nft-page .staking-heading-copy .nft-reward-timing{margin:2px 0 0;font-size:12px;line-height:1.4;text-align:start;color:var(--ui-muted);font-variant-numeric:tabular-nums}
.staking-heading-copy .nft-reward-timing p{margin:0}
body[data-ui=nfts].staking-page.nft-page .staking-personal .nft-characters{display:none}
body[data-ui=nfts].staking-page.nft-page .staking-personal .nft-navigation{display:flex;align-items:center;justify-content:space-between;flex-wrap:nowrap;gap:16px;width:100%;max-width:none;min-height:46px;margin:0}
