.nft-panel{min-height:var(--nft-panel-floor,130px)}.nft-panel.entering{animation:nft-panel-in .28s cubic-bezier(.25,.46,.45,.94)}.nft-panel p{max-width:670px}.nft-panel>p:first-child{margin-top:0}.nft-panel h2{font-size:24px;font-weight:500;margin:0 0 12px}
