.nft-card .nft-seller{display:flex;flex-wrap:wrap;gap:0 5px;font-size:15px;line-height:1.4;margin:5px 0 0}.nft-seller a{white-space:nowrap}
.nft-history{list-style:none;margin:0;padding:0}
.nft-history-row{display:grid;grid-template-columns:52px minmax(0,1fr) auto;column-gap:16px;row-gap:2px;align-items:center;padding:12px 0}
.nft-history-picture{grid-row:1/3}.nft-history-picture img{display:block;width:52px;height:52px;border-radius:50%}
.nft-history-details{grid-column:2;grid-row:1/3;min-width:0}.nft-history-title{font-size:19px;font-weight:500;margin:0!important}.nft-history-title a{text-decoration:none}.nft-history-title a:hover{text-decoration:underline}
.nft-history-people{font-size:16px;margin:2px 0 0!important;line-height:1.4}.nft-history-people a{white-space:nowrap}
.nft-history-amount{grid-column:3;grid-row:1;text-align:right;font-size:19px;font-weight:500;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}
.nft-history-time{grid-column:3;grid-row:2;text-align:right;font-size:15px;white-space:nowrap}
@media(max-width:700px){.nft-history-row{grid-template-columns:44px minmax(0,1fr);gap:3px 12px;padding:14px 0}.nft-history-picture{grid-row:1/4;align-self:start}.nft-history-picture img{width:44px;height:44px}.nft-history-details{grid-column:2;grid-row:1}.nft-history-amount{grid-column:2;grid-row:2;text-align:left;font-size:17px}.nft-history-time{grid-column:2;grid-row:3;text-align:left}.nft-history-title{font-size:18px}.nft-history-people{font-size:15px}}
.nft-status{font-size:18px;max-width:780px;overflow-wrap:anywhere}.nft-status:empty{display:none}.nft-status a{white-space:nowrap}
.nft-footer{display:flex;flex-wrap:wrap;gap:8px 24px;margin-top:28px;font-size:17px}.nft-footer a{display:inline-flex;align-items:center;min-height:44px;text-decoration:none}.nft-footer a:hover{text-decoration:underline}
.nft-page dialog{color:#000;background:#EC673A;border:1px solid #000;max-width:440px;width:calc(100vw - 32px);max-height:calc(100dvh - 32px);overflow:auto;padding:28px;box-shadow:none;overscroll-font-weight:500;line-height:1.2;margin:0 28px 18px 0}.action-body{overflow-wrap:anywhere}.action-body p{margin:0 0 14px}.action-body p:last-child{margin-bottom:0}
.dialog-close{position:absolute;right:12px;top:8px;font-size:28px!important;text-decoration:none;min-width:44px;min-height:44px}
.wallet-options{display:grid;gap:8px}.wallet-options button{display:flex;align-items:center;gap:16px;text-align:left;padding:10px 0;text-decoration:none}.wallet-options button:hover{text-decoration:underline}.wallet-options img{width:34px;height:34px;object-fit:contain}
.nft-page input{background:none;border:0;border-bottom:1px solid #000;border-radius:0;width:100%;padding:8px 0;margin:10px 0 4px;font-size:20px;min-height:44px}
.dialog-actions{display:flex;justify-content:flex-end;gap:20px;margin-top:22px}.nft-price-summary{font-size:18px;overflow-wrap:anywhere}.nft-more{margin-top:20px}.nft-empty{min-height:44px;font-size:20px}
@keyframes nft-dialog-in{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:700px){.nft-page{padding:20px 22px 30px;font-size:20px}.nft-header{margin-bottom:26px;gap:12px}.nft-header nav{gap:17px;font-size:16px}.brand-link,.brand-link svg{width:42px;height:42px}.social-link,.social-link svg{width:25px}.wallet-button{gap:7px}.wallet-icon{width:21px;height:21px}.nft-characters{margin:18px -10px 14px}.nft-flow{gap:10px;margin-bottom:22px}.nft-flow svg{width:75px;height:55px}.nft-flow p{font-size:17px}.nft-explain{font-size:20px;line-height:1.4}.nft-stats{grid-template-columns:repeat(2,minmax(0,1fr));gap:20px 10px;margin:26px 0}.nft-stat:last-child{grid-column:1/-1}.nft-stat strong{font-size:26px}.nft-stat span{font-size:16px;display:block;line-height:1.2;margin-top:5px}.nft-navigation{gap:0 18px;margin-top:22px}.nft-tabs{gap:clamp(5px,2.5vw,18px)}.nft-opensea{font-size:19px}.nft-tabs button{font-size:19px}.nft-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:22px 16px}.nft-footer{gap:4px 22px;font-size:16px}.nft-panel{min-height:var(--nft-panel-floor,120px)}.nft-page dialog{padding:26px 22px}}
@media(max-width:370px){.nft-page{padding-inline:17px}.nft-header nav{gap:12px;font-size:15px}.wallet-icon{width:18px;height:18px}.nft-stat strong{font-size:23px}.nft-tabs{gap:5px}.nft-tabs button,.nft-opensea{font-size:17px}.nft-flow p{font-size:16px}.nft-explain{font-size:19px}}
