.mint-costs{display:grid;grid-template-columns:auto 1fr;gap:12px 18px;margin:0 0 22px}.mint-costs dt{font-size:18px}.mint-costs dd{margin:0;text-align:right;font-weight:500;overflow-wrap:anywhere}
#saved-action p{margin:0}#saved-action{margin:18px 0}
@media(max-width:500px){#disconnect{flex-direction:column;gap:0;line-height:1.25;font-size:14px}#wallet-address{font-size:12px}}

