/* Shared type, spacing and interaction rules for the public Claus pages. */
:root {
  --page-title: clamp(34px, 4vw, 46px);
  --section-title: clamp(23px, 2.2vw, 27px);
  --body-copy: 20px;
  --small-copy: 17px;
  --ui-ease: cubic-bezier(.23, 1, .32, 1);
}
a, button { text-decoration-thickness: 1px; text-underline-offset: 4px; }
h1, h2, h3 { text-wrap: balance; }
.note, .note-detail, .function-list p, .log-list p, .hook-structure p {
  text-align: start;
  text-align-last: auto;
  -webkit-hyphens: none;
  hyphens: none;
  text-wrap: pretty;
}
.notes-shell { transition: none; }
.claus-story { line-height: 1.48; transition: none; }
.claus-about { display: block; }
.claus-about > .page-window { height: 100%; overflow-y: auto; overflow-x: hidden; scrollbar-width: thin; scrollbar-color: #0005 transparent; padding-right: 8px; }
.claus-about .page-flow { height: auto; columns: auto; transform: none !important; padding-bottom: 16px; }
.claus-about > .page-controls { display: none; }
.note-detail { margin-top: 22px; }
.functions-heading { justify-content: space-between; gap: 8px 18px; }
.function-list li + li { margin-top: 18px; }
.log-entry-heading { column-gap: 12px; row-gap: 2px; }
.log-list p { line-height: 1.5; }
.journal-entry-heading { margin-bottom: 28px; }
#journal-entry-title { font-size: var(--page-title); line-height: 1.12; letter-spacing: -.02em; }
#journal-entry-body { max-width: 64ch; }
.journal-source { font-size: var(--small-copy); }
.journal-source a { min-height: 44px; display: inline-flex; align-items: center; }
.hooks-article > .journal-title { margin-bottom: 32px; }
#hooks-heading, .burn-heading h1, .arena-heading h1 {
  font-size: var(--page-title);
  font-weight: 500;
  letter-spacing: -.025em;
  line-height: 1.15;
}
#hooks-total { font-size: inherit; font-weight: inherit; }
.hook-structure { gap: 0 32px; margin-bottom: 36px; }
.hook-structure h2 { font-size: var(--section-title); }
.hook-structure p, #all-hooks p { font-size: 19px; line-height: 1.5; }
#all-hooks { gap: 32px 40px; }
#all-hooks li { padding-top: 0; }
#all-hooks h2 { font-size: 24px; margin-bottom: 8px; }
.burn-heading { align-items: baseline; }
.burn-back { padding: 10px 0; font-size: 18px; }
.burn-overview { padding-top: 24px; }
.burn-explanation { font-size: 21px; line-height: 1.5; max-width: 42ch; }
.burn-sources { gap: 8px 28px; font-size: var(--small-copy); margin-top: 24px; }
.hook-steps { width: min(100%, 540px); gap: 24px; margin-top: 32px; }
.hook-steps li + li::before, .hook-steps li + li::after { content: none; }
.hook-steps .step-number { border: 0; width: auto; height: auto; font-size: 16px; margin-bottom: 8px; }
.hook-steps strong { font-size: 20px; }
.hook-steps li > span:last-child { font-size: 16px; line-height: 1.4; opacity: 1; }
.weather-source-note { font-size: var(--small-copy); }
.hook-intro, .burn-article > .hook-intro {
  max-width: 58ch;
  margin: 14px 0 24px;
  font-size: var(--body-copy);
  line-height: 1.5;
  text-align: start;
  text-wrap: pretty;
}
.burn-article > .hook-intro + .burn-overview { padding-top: 8px; }
.hook-steps li > span:last-child { margin-top: 8px; line-height: 1.45; }
.weather-step small { max-width: 20ch; font-size: 16px; line-height: 1.45; opacity: 1; }
.rules h3 { margin: 24px 0 8px; font-size: 21px; font-weight: 500; }
.rules p { max-width: 70ch; }

/* App pages use the same header proportions and text scale. */
.nft-page, .prediction-page { max-width: 1080px; padding: 28px 32px 44px; line-height: 1.5; }
.nft-header, .prediction-header { gap: 20px; margin-bottom: 30px; }
.nft-header nav, .prediction-header nav { gap: 4px 24px; font-size: 18px; }
.nft-header .header-socials, .prediction-header .header-socials { gap: 20px; }
.nft-header .social-link, .prediction-header .social-link { width: 30px; min-height: 44px; }
.nft-header .social-link svg, .prediction-header .social-link svg { width: 28px; height: 28px; }
.nft-title h1, .hero h1 { font-size: var(--page-title); line-height: 1.12; letter-spacing: -.025em; }
.solid-button { transition: transform 140ms var(--ui-ease), opacity 140ms ease; }
.solid-button:active:not(:disabled), .side-button:active:not(:disabled) { transform: scale(.96); }
.nft-panel.entering { animation-duration: 180ms; }

/* Keep the collection explanation close to the market it describes. */
.nft-characters { max-width: 690px; margin: 8px auto 12px; }
.nft-flow { max-width: 800px; gap: 24px; margin-bottom: 24px; }
.nft-flow svg { width: 82px; height: 56px; margin-bottom: 8px; }
.nft-flow p { font-size: 19px; line-height: 1.4; }
.nft-explain { max-width: 680px; font-size: 20px; line-height: 1.5; margin-bottom: 0; }
.nft-explain p + p { margin-top: 8px; font-size: 17px; }
.nft-stats { max-width: 900px; gap: 24px; margin: 32px auto; }
.nft-stat strong { font-size: 32px; line-height: 1.2; }
.nft-stat span { display: block; margin-top: 5px; font-size: 17px; line-height: 1.35; }
.nft-navigation { margin: 0 0 28px; gap: 0 28px; }
.nft-tabs { gap: 28px; }
.nft-tabs button, .nft-opensea { font-size: 21px; }
.nft-tabs button::after { transition: opacity 140ms ease, transform 140ms var(--ui-ease); }
.nft-grid { gap: 32px 24px; }
.nft-card h3 { font-size: 22px; margin-top: 10px; }
.nft-card-actions { gap: 0 20px; }
.nft-footer { margin-top: 36px; }
.nft-page dialog h2 { margin-right: 56px; }
.nft-page .dialog-close { font-size: 16px !important; right: 20px; top: 16px; }

/* The decision and the live value lead; the mascot sits alongside them. */
.hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 210px;
  column-gap: 40px;
  align-content: center;
  text-align: start;
  padding: 10px 0 36px;
}
.hero h1, .hero .intro, .hero .current-cap, .hero .pool-rule { grid-column: 1; }
.hero h1 { margin: 0 0 16px; }
.hero .intro { font-size: 25px; line-height: 1.3; text-wrap: pretty; }
.hero .prediction-art { grid-column: 2; grid-row: 1 / span 4; align-self: center; width: 100%; margin: 0; }
.hero .current-cap { margin-top: 10px; font-size: 22px; }
.hero .pool-rule { max-width: 52ch; margin: 14px 0 0; font-size: 17px; line-height: 1.5; }
.market-toolbar { margin-bottom: 24px; min-height: 48px; }
.market-toolbar [role=tab] { font-size: 22px; }
.market-grid { align-items: start; min-height: 200px; }
.market-card { padding: 24px; min-height: 250px; }
.market-card h2 { margin: 8px 0 14px; }
.market-card .time-detail { line-height: 1.4; }
.how { margin-top: 44px; margin-bottom: 28px; }
.how h2 { font-size: var(--section-title); margin-bottom: 24px; }
.how ol { gap: 32px; }
.how h3 { font-size: 22px; line-height: 1.25; margin-bottom: 8px; }
.how p { font-size: 18px; line-height: 1.5; }
.prediction-page footer { font-size: var(--small-copy); }
.prediction-page footer a { min-height: 44px; display: inline-flex; align-items: center; }

@media (max-width: 700px) {
  .nft-page, .prediction-page { padding: 20px 22px 32px; }
  .nft-header, .prediction-header { margin-bottom: 24px; }
  .nft-header nav, .prediction-header nav { gap: 4px 16px; font-size: 16px; }
  .nft-header .header-socials, .prediction-header .header-socials { gap: 16px; }
  .nft-header .social-link, .prediction-header .social-link { width: 26px; }
  .nft-header .social-link svg, .prediction-header .social-link svg { width: 26px; height: 26px; }
  .nft-characters { margin: 12px -8px 18px; }
  .nft-flow { gap: 12px; margin-bottom: 24px; }
  .nft-flow svg { width: 68px; height: 48px; }
  .nft-flow p { font-size: 16px; }
  .nft-flow strong { font-size: 16px; }
  .nft-flow strong span { display: block; }
  .nft-explain { font-size: 19px; }
  .nft-explain p + p { font-size: 16px; }
  .nft-stats { gap: 20px 12px; margin: 28px 0; }
  .nft-stat strong { font-size: 27px; }
  .nft-stat span { font-size: 16px; }
  .nft-navigation { gap: 0 18px; margin-bottom: 24px; }
  .nft-tabs { gap: clamp(8px, 3vw, 18px); }
  .nft-tabs button, .nft-opensea { font-size: 19px; }
  .nft-grid { gap: 28px 16px; }
  .nft-card h3 { font-size: 20px; }
  .hero { grid-template-columns: minmax(0, 1fr) 96px; column-gap: 16px; padding: 8px 0 28px; }
  .hero h1 { grid-column: 1; margin-bottom: 12px; }
  .hero .prediction-art { grid-row: 1 / span 2; }
  .hero .intro { font-size: 22px; }
  .hero .current-cap, .hero .pool-rule { grid-column: 1 / -1; }
  .hero .current-cap { margin-top: 18px; font-size: 21px; }
  .hero .pool-rule { font-size: 17px; margin-top: 10px; }
  .market-toolbar { justify-content: space-between; gap: 12px 20px; }
  .market-toolbar [role=tablist] { gap: 22px; }
  .market-toolbar .solid-button { width: 100%; }
  .market-grid { min-height: 180px; }
  .market-card { min-height: 240px; }
  .how { margin-top: 32px; }
  .how ol { gap: 24px; }
  .burn-heading h1 { font-size: 32px; }
  #hooks-heading { font-size: 28px; }
  .burn-back { font-size: 17px; }
  .hook-structure { margin-bottom: 32px; }
  #all-hooks { gap: 28px; }
  .hook-steps { gap: 12px; }
  .hook-steps strong { font-size: 18px; }
  .hook-steps li > span:last-child { font-size: 15px; }
}
@media (max-width: 850px) {
  .claus-about > .page-window { height: auto; overflow: visible; padding-right: 0; }
}
@media (max-width: 370px) {
  .nft-page, .prediction-page { padding-inline: 18px; }
  .nft-header nav, .prediction-header nav { gap: 4px 12px; }
  .nft-tabs { gap: 10px; }
  .nft-tabs button, .nft-opensea { font-size: 17px; }
  .nft-flow { gap: 8px; }
  .nft-flow p { font-size: 15px; }
  .hero { grid-template-columns: minmax(0, 1fr) 76px; column-gap: 12px; }
  .hero .intro { font-size: 20px; }
  .burn-heading { flex-wrap: wrap; gap: 4px 20px; }
  #hooks-heading { font-size: 26px; }
}
@media (prefers-reduced-motion: reduce) {
  .solid-button, .side-button, .nft-tabs button::after { transition: none; }
  .solid-button:active:not(:disabled), .side-button:active:not(:disabled) { transform: none; }
  .nft-panel.entering { animation: none; }
}

/* Keep the three-step explanations and source links consistent. */
.weather-flow { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 24px; }
.hook-flow li:not(:last-child)::after { content: none; }
.hook-flow li { line-height: 1.45; }
#close-help { width: auto; min-width: 44px; font-size: 17px; right: 20px; }
#hook-details h2 { margin-right: 56px; }
#hook-details .hook-detail-note { font-size: 19px; }
@media (max-width: 700px) {
  .weather-flow { gap: 12px; }
  .weather-step small { font-size: 15px; }
  .hook-intro, .burn-article > .hook-intro { font-size: 19px; margin-bottom: 20px; }
}

styles.45bcb7440a7b25351c1f:
/* Shared frame for hooks with controls; no separate explanation/splash page. */
@font-face{font-family:ClausSans;src:url("archive-asset:59467fa0151050b34dc1") format('woff2');font-weight:100 1000;font-display:swap}
.hook-module{font-family:ClausSans,Arial,sans-serif;font-size:17px}
.hook-module button,.hook-module input,.hook-module select{font:inherit}
.hook-module a,.hook-module .text-button{text-decoration:none}
.hook-module a:hover,.hook-module .text-button:hover{text-decoration:underline;text-decoration-thickness:2px;text-underline-offset:4px}
.hook-module{width:100%;max-width:1080px;margin:0 auto;padding:24px 32px 40px}
.hook-module main{width:100%;min-width:0}
.hook-module>header{margin:0 0 24px;display:flex;align-items:center;justify-content:space-between;gap:20px}
.hook-module h1{text-align:center;font-size:clamp(30px,4vw,42px);line-height:1.15;letter-spacing:-.03em;margin:0 0 18px}
.hook-module .module-intro{max-width:680px;margin:0 auto 28px;font-size:17px;line-height:1.6;text-align:center;text-wrap:balance}
.hook-module .module-intro p{font-size:inherit;line-height:inherit}
.hook-module .module-intro p+p{margin-top:12px}
.hook-module .nft-characters{width:min(100%,490px);margin:0 auto 16px}
.hook-module .nft-stats{margin:28px auto}
.hook-module .hero{grid-template-columns:minmax(0,1fr) 190px;padding:0 0 26px;gap:0 32px}
.hook-module .hero h1{text-align:start}
.hook-module .hero .intro{font-size:20px;line-height:1.5}
.hook-module .hero .pool-rule{font-size:16px}
.hook-module .how{margin-top:32px}
.hook-module .arena-heading{justify-content:center}
.hook-module .hook-explainer{margin:20px auto}
.hook-module footer{display:flex;justify-content:center;flex-wrap:wrap;gap:12px 24px;font-size:15px}
@media(max-width:700px){
 .hook-module{padding:16px 22px 30px}
 .hook-module>header{margin-bottom:22px;gap:12px}
 .hook-module .module-intro{font-size:16px;margin-bottom:22px}
 .hook-module .hero{display:flex;flex-direction:column;align-items:center;text-align:center;gap:12px}
 .hook-module .hero h1{text-align:center;margin:0}
 .hook-module .hero .prediction-art{width:130px;order:-1}
 .hook-module .hero .intro{font-size:18px}
 .hook-module .hero .pool-rule{margin:0}
}

.module-details{max-width:680px;margin:32px auto 0;font-size:17px;line-height:1.6}
.module-details summary{width:fit-content;margin:auto;cursor:pointer;font-weight:500;min-height:44px;display:flex;align-items:center;gap:10px;list-style:none}
.module-details summary::-webkit-details-marker{display:none}
.module-details summary::after{content:'+';font-size:22px;font-weight:400}
.module-details[open] summary::after{content:'−'}
.module-details p{margin:14px 0;text-wrap:pretty}
.module-details p:last-child a{display:inline-block;margin:0 16px 0 0;min-height:44px;align-content:center}
@media(min-width:701px){.hook-module .nft-grid{grid-template-columns:repeat(auto-fit,minmax(210px,236px));justify-content:center}}

/* Privacy uses the shared frame while preserving its deposit/recovery controls. */
.hook-module.privacy-page>.privacy-header{padding:0;max-width:none}
.hook-module.privacy-page>.privacy-main{padding:0;max-width:none;justify-content:flex-start}
.hook-module .privacy-layout{gap:32px;align-items:start}
.hook-module .privacy-character{width:min(100%,240px)}
.hook-module .privacy-title h1{font-size:clamp(30px,4vw,42px)}
.hook-module .privacy-intro{max-width:410px;font-size:17px;line-height:1.6}
.hook-module .privacy-title p{font:inherit}
.hook-module .purchase{padding-top:18px}
.hook-module .privacy-main>footer{margin-top:32px}
.hook-module .privacy-details{font-size:16px;line-height:1.6}
@media(max-width:700px){.hook-module .privacy-layout{grid-template-columns:1fr;gap:24px}.hook-module .privacy-character{width:150px}.hook-module .privacy-intro{max-width:100%}.hook-module .purchase{padding-top:0}.hook-module .privacy-title p{font-size:16px}}
.hook-module h1{font-weight:550}
.hook-module .how details.module-details{max-width:680px;margin:24px auto 0}
.hook-module .how details.module-details>summary{display:flex;text-decoration:none}
.hook-module .hero>h1{grid-column:1/-1;text-align:center}
.hook-module .hero>.prediction-art{grid-row:2/span 3;width:min(100%,165px);justify-self:center}
.hook-module .module-details>summary:hover{text-decoration:underline;text-underline-offset:4px}

/* Collection totals share the hook pages' result-first typography. */
.hook-module .nft-stats{max-width:100%;gap:28px 20px;margin:32px auto 28px}
.hook-module .nft-stat strong{font-size:clamp(34px,4.4vw,56px);font-weight:600;line-height:1.1;letter-spacing:0;min-height:1.1em}
.hook-module .nft-stat span{font-size:15px;line-height:1.4;margin-top:9px}
.hook-module .nft-navigation{justify-content:center;margin-top:24px}
.hook-module .nft-tabs{gap:28px}
.hook-module #panel-mint{text-align:center}
.hook-module #mint-description{max-width:530px;margin:0 auto 20px;font-size:16px;line-height:1.6}
.hook-module .nft-panel{padding-top:22px}
@media(max-width:700px){
 .hook-module .nft-stats{grid-template-columns:repeat(2,minmax(0,1fr));gap:24px 16px}
 .hook-module .nft-stat strong{font-size:clamp(29px,7.4vw,48px)}
 .hook-module .nft-stat:last-child strong{font-size:clamp(42px,11vw,58px)}
 .hook-module .nft-tabs{gap:20px}
 .hook-module .nft-tabs button,.hook-module .nft-opensea{font-size:17px}
}

/* Explanatory copy shares a centered axis; controls keep their own alignment. */
.hook-module .module-intro p,.hook-module .module-details>p{margin-inline:auto;text-align:center;text-wrap:balance}
.hook-module .module-details>h2,.hook-module .module-details>h3{text-align:center}
.hook-module .module-details p:last-child a{margin-inline:8px}
.hook-module .privacy-intro,.hook-module .hero .intro,.hook-module .hero .pool-rule,.hook-module .hero .current-cap{margin-inline:auto;text-align:center;text-wrap:balance}
.hook-module :is(.market-card h2,.amount-field input,.review-row strong,.current-cap strong){letter-spacing:0;font-variant-numeric:lining-nums tabular-nums}
.hook-module .nft-stat{min-width:0}
.hook-module .nft-stat strong{font-variant-numeric:lining-nums tabular-nums}
.hook-module :is(.nft-empty,.nft-status){margin-inline:auto;text-align:center;text-wrap:balance}
@media(max-width:500px){
 .hook-module .nft-stats{grid-template-columns:1fr;gap:24px}
 .hook-module .nft-stat strong,.hook-module .nft-stat:last-child strong{font-size:clamp(40px,11vw,52px)}
}

styles.6f488a3b23060490ffc0:
body[data-ui=project],body[data-ui=project] *{box-sizing:border-box}
html,body{margin:0;background:#ec673a;color:#181818;font-family:Claus UI,Arial,sans-serif}
body{min-height:100svh;background:radial-gradient(ellipse at 48% 41%,#f68859 0%,#ee7144 39%,#e96436 78%)}
.project-skip{position:fixed;top:12px;left:12px;z-index:30;padding:12px;background:#181818;color:#fff2d8;translate:0 -160%}
.project-skip:focus{translate:0}
.network-profile-header{display:flex;align-items:center;gap:28px;max-width:1280px;padding:16px 32px;margin:auto}
.network-profile-header .atlas-brand{display:block;flex:none;width:110px;height:110px;color:inherit}
.network-profile-header .atlas-brand svg{display:block;width:100%;height:100%}
.network-profile-header h1{font-size:var(--ui-title);font-weight:600;line-height:1.05;letter-spacing:-.05em;margin:0;overflow-wrap:anywhere}
.network-profile{max-width:1000px;margin:8px auto 0;padding:20px 32px 150px;min-height:0}
.project-stage{display:inline-block;font-size:14px;padding:9px 13px;border:1px solid #18181870;border-radius:24px}
.project-description{font-size:clamp(18px,2vw,24px);line-height:1.5;max-width:42em;margin:24px 0 36px;white-space:pre-wrap;overflow-wrap:anywhere}
.network-profile section{margin:32px 0}
.network-profile h2{font-size:20px;font-weight:600;letter-spacing:-.02em;margin:0 0 16px}
.project-evidence{display:flex;align-items:center;flex-wrap:wrap;gap:12px 24px;padding:14px 0;border-top:1px solid #18181830}
.project-evidence a{color:inherit;overflow-wrap:anywhere;text-underline-offset:4px;min-height:24px}
#project-content[aria-busy=true]{min-height:160px}
#project-content[aria-busy=true]::before{content:'';display:block;width:min(320px,80%);height:22px;background:#1818180d;border-radius:8px;margin:24px 0}
#project-status{font-size:15px;line-height:1.5}
@media(max-width:600px){.network-profile-header{gap:14px;padding:12px 16px}.network-profile-header .atlas-brand{width:82px;height:82px}.network-profile-header h1{font-size:var(--ui-title)}.network-profile{padding:16px 22px 140px}.project-evidence{display:grid;gap:9px}}
@media(prefers-reduced-motion:reduce){*{scroll-height:auto;min-height:0;width:100%;max-width:1280px;margin:0 auto;padding:var(--ui-title-top,18px) 124px 22px}
#project-header h1{text-align:center;font-size:var(--ui-title);font-weight:550;line-height:1.08;letter-spacing:-.04em}
#project-main{width:min(100%,1000px);padding:18px 28px 28px;margin:0 auto}
@media(max-width:700px){#project-header{padding:var(--ui-title-top,76px) 20px 16px}#project-main{padding:12px 20px 24px}.project-description{margin:18px 0 28px}}
@media(max-height:500px) and (orientation:landscape){#project-header{padding:var(--ui-title-top,12px) 88px 12px}}
